## Why This Is Asked

Practical beginner task that mirrors real app patterns: data loading, caching, and offline UX.

## Key Concepts

- FlatList usage with data props
- AsyncStorage caching with versioned keys
- Offline-first UX with fallback data
- Simple search filtering

## Code Example

```javascript
import React, { useEffect, useState } from 'react';
import { FlatList, TextInput, View, Text } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

const API = 'https://example.com/api/coupons';
export default function CouponList() {
  const [data, setData] = useState([]);
  const [query, setQuery] = useState('');
  const [refreshing, setRefreshing] = useState(false);

  async function loadCache() {
    const cached = await AsyncStorage.getItem('coupons_v1');
    if (cached) setData(JSON.parse(cached));
  }

  async function fetchData() {
    try {
      const resp = await fetch(API);
      const json = await resp.json();
      setData(json);
      await AsyncStorage.setItem('coupons_v1', JSON.stringify(json));
    } catch (e) {
      // offline or error
    }
  }

  useEffect(() => { loadCache(); fetchData(); }, []);

  const filtered = data.filter(c => c.title.toLowerCase().includes(query.toLowerCase()));
  return (
    <View>
      <TextInput value={query} onChangeText={setQuery} placeholder="Search coupons" />
      <FlatList data={filtered} keyExtractor={item => item.id} renderItem={({item}) => <Text>{item.title}</Text>} />
    </View>
  );
}
```

